import{_ as a,o as r,c as t,a6 as o}from"./chunks/framework.DNkVJs23.js";const f=JSON.parse('{"title":"개인정보 처리방침","description":"개인정보 처리방침 — Sapphire Star Codex","frontmatter":{"description":"개인정보 처리방침 — Sapphire Star Codex","head":[["link",{"rel":"canonical","href":"https://eurekaffeine.github.io/sapphire-star-codex/ko/privacy/"}],["meta",{"property":"og:url","content":"https://eurekaffeine.github.io/sapphire-star-codex/ko/privacy/"}],["meta",{"property":"og:title","content":"개인정보 처리방침 | Sapphire Star Codex"}],["meta",{"property":"og:description","content":"개인정보 처리방침 — Sapphire Star Codex"}]]},"headers":[],"relativePath":"ko/privacy/index.md","filePath":"ko/privacy/index.md"}'),i={name:"ko/privacy/index.md"};function n(p,e,l,h,c,s){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="개인정보-처리방침" tabindex="-1">개인정보 처리방침 <a class="header-anchor" href="#개인정보-처리방침" aria-label="Permalink to &quot;개인정보 처리방침&quot;">​</a></h1><p>시행일: 2026년 10월 31일. 원문 최종 수정일: 2026년 11월 10일. 번역일: 2026년 11월 14일.</p><p>이 방침은 Sapphire Star Codex의 iOS, Android, HarmonyOS 앱과 이 사이트에 적용됩니다. 개발자: <strong>eurekaffeine (刘耀晨)</strong>. 연락처: <a href="mailto:eurekaffeine.work@gmail.com" target="_blank" rel="noreferrer">eurekaffeine.work@gmail.com</a>. 플랫폼별 기능은 다를 수 있으며 계정 등록은 필요하지 않습니다.</p><h2 id="기기에-저장되는-자료" tabindex="-1">기기에 저장되는 자료 <a class="header-anchor" href="#기기에-저장되는-자료" aria-label="Permalink to &quot;기기에 저장되는 자료&quot;">​</a></h2><p>앱은 게임·언어·화면 설정, 검색 기록과 화면 복원 상태, 즐겨찾기, 저장한 방어구 세트와 이름, 장식주·호석·방어구 보유 내역을 기기에 저장합니다. 이는 앱 기능 제공에 사용되며 개발자에게 업로드되지 않습니다. 개발자는 계정이나 클라우드 동기화 서비스를 운영하지 않습니다.</p><h2 id="권한과-자동-수집" tabindex="-1">권한과 자동 수집 <a class="header-anchor" href="#권한과-자동-수집" aria-label="Permalink to &quot;권한과 자동 수집&quot;">​</a></h2><p>앱에는 광고, 추적, 사용 통계 또는 오류 보고서 자동 전송 SDK가 없습니다. 현재 기능은 연락처, 위치, 카메라, 마이크, 사진 접근을 요구하지 않으며 광고 식별자를 수집하지 않습니다. 운영체제와 앱 스토어는 각자의 정책에 따라 설치·진단 정보를 처리할 수 있습니다. 개발자에게 제공되는 진단 정보는 문제 해결에만 사용합니다.</p><h2 id="이메일과-외부-서비스" tabindex="-1">이메일과 외부 서비스 <a class="header-anchor" href="#이메일과-외부-서비스" aria-label="Permalink to &quot;이메일과 외부 서비스&quot;">​</a></h2><p>자발적으로 이메일을 보내면 개발자는 발신 주소, 메시지와 첨부파일을 받습니다. 답변, 문제 조사와 개인정보 요청 처리에만 사용하며 마케팅에는 사용하지 않습니다. 필요한 정보만 보내 주세요. Gmail의 정보 처리는 <a href="https://policies.google.com/privacy" target="_blank" rel="noreferrer">Google 개인정보처리방침</a>을 따릅니다.</p><p>이 사이트는 GitHub Pages에서 제공하며 IP 주소와 브라우저의 기술 정보 등이 처리될 수 있습니다. <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement" target="_blank" rel="noreferrer">GitHub 개인정보처리방침</a>을 참고하세요. 별도의 방문 통계, 광고 쿠키나 추적 픽셀은 추가하지 않습니다. 검색은 브라우저 안에서 실행되며 표시·검색 설정이 저장될 수 있습니다. 외부 서비스에는 해당 서비스의 정책이 적용되며 거주 국가 밖에서 정보를 처리할 수 있습니다.</p><h2 id="후원과-백업" tabindex="-1">후원과 백업 <a class="header-anchor" href="#후원과-백업" aria-label="Permalink to &quot;후원과 백업&quot;">​</a></h2><p>후원금은 Alipay 또는 WeChat Pay의 약관과 방침에 따라 처리됩니다. 사이트는 정적 QR 코드만 표시하며 결제 SDK를 사용하거나 결제 인증정보를 받지 않습니다. 개발자는 후원 확인과 문제 해결을 위해 플랫폼이 수취인에게 제공하는 금액, 시각, 표시 이름, 메모 등을 볼 수 있습니다. 보관에는 플랫폼 규칙과 적용되는 기록 보관 의무가 따릅니다. 시스템 설정에 따라 앱 자료가 기기 또는 클라우드 백업에 포함될 수 있으며 개발자는 이를 읽거나 삭제할 수 없습니다.</p><h2 id="제공-보관과-삭제" tabindex="-1">제공, 보관과 삭제 <a class="header-anchor" href="#제공-보관과-삭제" aria-label="Permalink to &quot;제공, 보관과 삭제&quot;">​</a></h2><p>개발자는 개인정보를 판매·대여하거나 광고 목적으로 공유하지 않습니다. 이메일은 위의 서비스 제공자가 처리합니다. 법적 의무나 명시적 요청에 따라 실제 보유한 정보를 제공할 수 있습니다.</p><p>앱 기능이나 시스템 설정에서 기기 자료를 삭제할 수 있습니다. 자료를 유지하는 삭제·보관 기능은 데이터를 지우지 않으며, 백업은 별도로 관리해야 합니다. 재설치 시 자료가 복원될 수 있습니다. 사이트 설정은 직접 지우거나 브라우저가 정리할 때까지 남습니다. 이메일은 요청 처리, 후속 지원 또는 법적 의무에 필요한 기간만 보관합니다. 서비스 제공자의 로그와 백업은 각 제공자가 관리합니다. 전송한 정보의 열람·정정·삭제는 연락처로 요청할 수 있으며 법적 보관 의무가 우선할 수 있습니다. 기기에만 있는 자료에는 개발자가 원격 접근할 수 없습니다.</p><h2 id="보안-미성년자와-방침-변경" tabindex="-1">보안, 미성년자와 방침 변경 <a class="header-anchor" href="#보안-미성년자와-방침-변경" aria-label="Permalink to &quot;보안, 미성년자와 방침 변경&quot;">​</a></h2><p>기기 자료는 운영체제의 저장소 보호 기능을 사용합니다. 사이트는 HTTPS를 사용하며 이메일 접근은 지원과 개인정보 요청 처리에 한정하고 메일 제공자의 보안 기능을 사용합니다. 앱은 개인 프로필이나 생년월일을 요구하지 않으며 아동의 정보를 의도적으로 수집하지 않습니다. 보호자는 아동이 보낸 정보의 삭제를 요청할 수 있습니다.</p><p>처리 방식이 바뀌면 방침과 날짜를 갱신합니다. 중요한 변경은 사이트나 앱 업데이트로 알립니다. 새 기능에 필요한 권한이나 동의는 별도로 요청하며, 이 방침 자체가 해당 동의를 대신하지 않습니다.</p><p><strong>eurekaffeine (刘耀晨)</strong> — <a href="mailto:eurekaffeine.work@gmail.com" target="_blank" rel="noreferrer">eurekaffeine.work@gmail.com</a></p>',19)])])}const m=a(i,[["render",n]]);export{f as __pageData,m as default};
